from pathlib import Path
import h5py, numpy as np
paths=sorted(Path('data').glob('sub-*/*.nwb'))[:2]
for p in paths:
 print('\nFILE',p)
 with h5py.File(p,'r') as f:
  for k in ['general/subject/subject_id','identifier','session_description']:
   print(k,f[k][()])
  tr=f['intervals/trials']
