   ds=tr[k]
   vals=ds[:min(12,len(ds))] if ds.shape else ds[()]
   if getattr(ds.dtype,'kind',None)=='O' and hasattr(vals,'__iter__'): vals=[x.decode() if isinstance(x,bytes) else x for x in vals]
   print('trial',k,'attrs',dict(ds.attrs),'first',vals)
  ev=f['acquisition/BehavioralEvents']
  for k in ['go_start_times','sample_start_times','photostim_start_times']:
   if k in ev:
    g=ev[k]
    print(k,'attrs',dict(g.attrs))
    for d in g:
     print(' ',d, g[d][:12] if g[d].shape else g[d][()])
  u=f['units']
  for k in ['classification','anno_name','unit_quality','is_good_trials']:
   a=u[k][:]
   if a.dtype.kind=='O': a=np.array([x.decode() if isinstance(x,bytes) else x for x in a])
   print('unit',k,'attrs',dict(u[k].attrs),'shape',a.shape,'unique/count', (np.unique(a,return_counts=True) if a.ndim==1 else np.mean(a)))
  t=f['acquisition/BehavioralTimeSeries/Camera0_side_TongueTracking']
  print('tongue attrs',dict(t.attrs),dict(t['data'].attrs), 'first',t['data'][:5], 'quantiles',np.quantile(t['data'][:], [0,.01,.1,.5,.9,.99,1],axis=0))
